DECLARE @SQL             NVARCHAR(MAX);
DECLARE @BODY            NVARCHAR(MAX);
DECLARE @HEADER          NVARCHAR(MAX);
DECLARE @STYLE           NVARCHAR(MAX);
DECLARE @COLUMN_HTML     NVARCHAR(MAX);
DECLARE @FULL_TABLE_NAME NVARCHAR(300);


SET @FULL_TABLE_NAME = N'D360.' + QUOTENAME(@TEMP_TABLE);


-- HTML STYLE - define the style for the HTML table
SET @STYLE = N'
<style>
    table {
        border-collapse: collapse;
        font-family: Aptos;
        font-size: 11pt;
    }

    th, td {
        text-align: left;
        padding: 5px;
        border: 1px solid #BFBFBF;
    }

    th {
        font-weight: bold;
        background-color: #E7E6E6;
    }

    tr:nth-child(2n) {
        background-color: #D6EEEE;
    }
</style>
';

-- Drop the temp table if it exists
SET @SQL = N'
IF OBJECT_ID(''' + @FULL_TABLE_NAME + N''') IS NOT NULL
BEGIN
    DROP TABLE ' + @FULL_TABLE_NAME + N';
END;
';

EXEC sp_executesql @SQL;


-- create the query as a table
SET @SQL = N'
CREATE TABLE ' + @FULL_TABLE_NAME + N'
WITH
(
    DISTRIBUTION = ROUND_ROBIN,
    HEAP
)
AS
' + @SOURCE_SQL + N';
';

EXEC sp_executesql @SQL;


-- get the columns of the temp table into another temp table for ease of use
IF OBJECT_ID('D360.TEMP_COLUMNS') IS NOT NULL
    DROP TABLE D360.TEMP_COLUMNS;

CREATE TABLE D360.TEMP_COLUMNS
(
    COLUMN_INDEX INT,
    COLUMN_NAME  NVARCHAR(128)
)
WITH
(
    DISTRIBUTION = ROUND_ROBIN,
    HEAP
);

INSERT INTO D360.TEMP_COLUMNS
(
    COLUMN_INDEX,
    COLUMN_NAME
)
SELECT
    ROW_NUMBER() OVER (ORDER BY ORDINAL_POSITION),
    COLUMN_NAME
FROM INFORMATION_SCHEMA.COLUMNS
WHERE TABLE_SCHEMA = 'D360'
  AND TABLE_NAME = @TEMP_TABLE;


-- create the first row of the HTML table with the column names

SELECT @HEADER =
    N'<table><tr>' +
    STRING_AGG(
        CAST(
            N'<th>' +
            REPLACE(
                REPLACE(
                    REPLACE(COLUMN_NAME, N'&', N'&amp;'),
                    N'<', N'&lt;'
                ),
                N'>', N'&gt;'
            ) +
            N'</th>'
            AS NVARCHAR(MAX)
        ),
        N''
    ) WITHIN GROUP (ORDER BY COLUMN_INDEX) +
    N'</tr>'
FROM D360.TEMP_COLUMNS;


-- create the HTML expression for all columns in the temp table
SELECT @COLUMN_HTML =
    STRING_AGG(
        CAST(
            N'''<td>'' + ' +
            N'ISNULL(CONVERT(NVARCHAR(MAX), ' +
            QUOTENAME(COLUMN_NAME) +
            N'), '''') + ' +
            N'''</td>'''
            AS NVARCHAR(MAX)
        ),
        N' + '
    ) WITHIN GROUP (ORDER BY COLUMN_INDEX)
FROM D360.TEMP_COLUMNS;



-- genreate the HTML table body with all rows from the temp table
SET @SQL = N'
SELECT @BODY_OUT =
    STRING_AGG(
        CAST(
            ''<tr>'' +
            ' + @COLUMN_HTML + N' +
            ''</tr>''
            AS NVARCHAR(MAX)
        ),
        ''''
    )
FROM ' + @FULL_TABLE_NAME + N';
';


EXEC sp_executesql
    @SQL,
    N'@BODY_OUT NVARCHAR(MAX) OUTPUT',
    @BODY_OUT = @BODY OUTPUT;


-- build the final HTML code
SET @BODY =
    @STYLE +
    ISNULL(@HEADER, N'<table>') +
    ISNULL(@BODY, N'') +
    N'</table>';

SELECT @BODY AS body;
